export type StockPhoto = (typeof stockPhotos)[keyof typeof stockPhotos];
/** Look up a stock photo by its public path (for content that references images by src). */
export const stockBySrc = (src: string): StockPhoto | undefined =>
  Object.values(stockPhotos).find((photo) => photo.src === src);
/** Variant widths generated for a master of the given width. */
export const variantWidths = (width: number) =>
  [480, 800, 1200].filter((w) => w < width);
